import os
from pathlib import Path

from .font_provider import BitmapProvider
from .pack import ResourcePack


def _rel(target: Path, start: Path) -> str:
    """ link path from the .md file's folder to target, with / separators """
    return Path(os.path.relpath(target, start)).as_posix()


def render_font_mappings(packs: list[ResourcePack], md_dir: Path) -> str:
    lines = [
        "# Font Mappings",
        "",
        "Generated by `py -m src font_mappings`. Do not edit by hand.",
        "",
    ]

    for pack in packs:
        providers = sorted(
            (p for p in pack.fonts if isinstance(p, BitmapProvider)),
            key=lambda p: ord(p.chars[0][0]) if p.chars and p.chars[0] else 0,
        )

        lines += [
            f"## {pack.path.name}",
            "",
            "| Preview | File | Unicode | Escape | Copy | Tellraw |",
            "|:-:|---|---|---|:-:|---|",
        ]

        esc = lambda c: f"\\u{ord(c):04X}"
        for p in providers:
            chars = [c for row in p.chars for c in row]

            img = _rel(p.texture_path(pack.path), md_dir)
            preview = f'<img src="{img}" height="16">'
            # unicode = ", ".join(f"\u+{ord(c):04X}" for c in chars)
            escape = " ".join(f"`{esc(c)}`" for c in chars)
            copy = " ".join(f"`{c}`" for c in chars)
            tellraw = f'`/tellraw @a {{"text":"{"".join(esc(c) for c in chars)}"}}`'

            lines.append(f"| {preview} | `{p.file}` | {0} | {escape} | {copy} | {tellraw} |")

        lines.append("")

    return "\n".join(lines)


def write_font_mappings(packs: list[ResourcePack], dest: Path) -> Path:
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(render_font_mappings(packs, dest.parent), encoding="utf-8")
    return dest
